#include <vector>
#include <algorithm>
using namespace std;

class Solution {
public:
    int maximumScore(vector<int>& nums, int k) {
        int n = nums.size();
        int l = k, r = k;
        int min_val = nums[k];
        int ans = min_val;

        while (l > 0 || r < n - 1) {
            int left_val = (l > 0) ? nums[l - 1] : -1;
            int right_val = (r < n - 1) ? nums[r + 1] : -1;
            if (left_val >= right_val) {
                l--;
                min_val = min(min_val, nums[l]);
            } else {
                r++;
                min_val = min(min_val, nums[r]);
            }
            ans = max(ans, min_val * (r - l + 1));
        }
        return ans;
    }
};

